// Kukicha Standard Library - Scalar Math
//
// Convenience math for single values, sized for shell-script ergonomics:
// Round returns an int (no `int(math.Round(...))` dance), Clamp works on
// any ordered type, and AbsInt covers the int case without dropping to
// math.Abs(float64). Two-arg min/max are Go built-ins — call `min(a, b)`
// / `max(a, b)` directly. Reach for the Go math package directly for
// Abs, Sqrt/Pow/Sin/etc.
//
// Examples:
//
//	nearest := math.Round(3.7)           # 4 (int)
//	priced  := math.RoundTo(3.14159, 2)  # 3.14
//	safe    := math.Clamp(value, 0, 100)
//	lower   := min(a, b)                 # Go builtin — no wrapper needed
package math

import (
	"cmp"
	gomath "math"
)

// AbsInt returns the absolute value of x as an int. Mirrors Python's
// bare `abs()` on ints — no Go-style `if x < 0 { x = -x }` boilerplate.
// Example: math.AbsInt(-42)  # 42
func AbsInt(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

// Round rounds x to the nearest integer, half-away-from-zero (matches
// Python's `round` semantics for whole-number targets). Returns int so
// the result drops straight into integer code.
// Example: math.Round(3.7)  # 4
func Round(x float64) int {
	return int(gomath.Round(x))
}

// RoundTo rounds x to `digits` decimal places. Negative digits are
// clamped to 0. Returns float64.
// Example: math.RoundTo(3.14159, 2)  # 3.14
func RoundTo(x float64, digits int) float64 {
	if digits < 0 {
		digits = 0
	}
	factor := gomath.Pow(10.0, float64(digits))
	return gomath.Round(x*factor) / factor
}

// Ceil returns the smallest integer >= x.
// Example: math.Ceil(2.1)  # 3
func Ceil(x float64) int {
	return int(gomath.Ceil(x))
}

// Floor returns the largest integer <= x.
// Example: math.Floor(2.9)  # 2
func Floor(x float64) int {
	return int(gomath.Floor(x))
}

// Clamp pins x into the inclusive range [lo, hi]. Returns lo if lo > hi.
// Example: math.Clamp(50, 0, 100)  # 50
func Clamp[T cmp.Ordered](x T, lo T, hi T) T {
	if x < lo {
		return lo
	}
	if x > hi {
		return hi
	}
	return x
}
